{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A sensory, premium sound bath series in {{CITY}}, {{STATE}} — restorative sessions led by {{FACILITATOR_NAME}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <link rel="icon" href="assets/img/pattern.svg">
</head>
<body class="aura">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Primary">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private Offerings</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">The Circle</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <div class="actions">
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button id="menuToggle" aria-label="menu">☰</button>
      </div>
    </div>
  </header>

  <main>
    <!-- HERO: minimal + poetic -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>A hush that remakes the body — a guided sound bath</h1>
          <p class="lede">An intimate, sensorial series of gatherings in {{CITY}} where tuned bowls and resonant spaces lead you home to calm. Led by {{FACILITATOR_NAME}}, our sessions are slow, premium, and carefully held.</p>
          <ul class="meta">
            <li><strong>Next gathering:</strong> {{NEXT_EVENT_DATE}}</li>
            <li><strong>Venue:</strong> {{VENUE_NAME}}</li>
            <li><strong>Phone:</strong> {{PHONE}}</li>
          </ul>
          <p class="hero-cta"><a class="btn" href="/events.html">See Next Event</a> <a class="ghost" href="/book.html">Book a private session</a></p>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg viewBox="0 0 600 400" preserveAspectRatio="xMidYMid slice" class="hero-blob">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#efdfef" />
                <stop offset="1" stop-color="#e6f7ff" />
              </linearGradient>
            </defs>
            <rect width="100%" height="100%" rx="20" fill="url(#g1)" />
            <g fill="none" stroke="#b3a6ff" stroke-opacity="0.4" stroke-width="6">
              <ellipse cx="300" cy="200" rx="170" ry="90" />
              <ellipse cx="310" cy="190" rx="130" ry="60" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF: subtle testimonials -->
    <section class="social-proof wrap">
      <h2>Whispers from the circle</h2>
      <div class="testimonials" id="testimonials">
        <blockquote>
          "A gentle architecture of sound — I left softer."
          <cite>— A. from {{CITY}}</cite>
        </blockquote>
        <blockquote>
          "Careful, precise, and deeply restful. The space felt sacred."
          <cite>— M.</cite>
        </blockquote>
        <blockquote>
          "A luxurious pause I gave to myself — and it returned me renewed."
          <cite>— R., studio teacher</cite>
        </blockquote>
      </div>
    </section>

    <!-- BENEFITS: sensory + premium -->
    <section class="benefits">
      <div class="wrap">
        <h2>What you feel — and why it matters</h2>
        <div class="cards">
          <article>
            <h3>Deep nervous system reset</h3>
            <p>Low sustained tones invite parasympathetic ease, lowering breath and settling muscles.</p>
          </article>
          <article>
            <h3>Sensory clarity</h3>
            <p>Focused listening refines attention — a soft meditation of sound and space.</p>
          </article>
          <article>
            <h3>Premium, meticulous holding</h3>
            <p>Intimate group sizes, curated acoustics, and hand-tuned instruments for a refined experience.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- PROCESS: the flow with instruments list unique -->
    <section class="process wrap">
      <h2>How an evening unfolds</h2>
      <ol class="flow">
        <li>
          <strong>Arrival & intention (15 min)</strong>
          <p>Settle. We offer tea and a quiet check-in to hold your intention for the practice.</p>
        </li>
        <li>
          <strong>Grounding sequence (10 min)</strong>
          <p>Gentle breath and stillness to orient the body towards listening.</p>
        </li>
        <li>
          <strong>Main sound journey (40–60 min)</strong>
          <p>Layered resonance from crystal bowls, chimes, and a large gong — tuned to guided waves that ebb and return.</p>
        </li>
        <li>
          <strong>Rest & reintegration (10–15 min)</strong>
          <p>Soft silence, optional journaling, and tea to integrate the experience.</p>
        </li>
      </ol>
      <p class="what-to-bring"><strong>What to bring:</strong> a yoga mat or pad, a blanket, an eye pillow or scarf, water, and any small comforts you prefer.</p>
      <p class="contra">Contraindications: If you are pregnant, have epilepsy, an active heart condition, or recent head injury, please consult your physician and contact us before attending. Some instruments produce intense vibration; we will accommodate where needed.</p>
    </section>

    <!-- FAQ: tailored + poetic -->
    <section class="faq wrap" id="faq">
      <h2>Questions we often hear</h2>
      <details>
        <summary>How long is each session?</summary>
        <p>Group sessions typically last 75—90 minutes including arrival and closing. Private sessions vary by booking.</p>
      </details>
      <details>
        <summary>Is the sound loud?</summary>
        <p>Volume is curated for comfort. The room resonates; you may feel vibrations. We adapt for sensitivity.</p>
      </details>
      <details>
        <summary>Can I fall asleep?</summary>
        <p>Yes — and it is fine. The work continues beneath waking; we support gentle re-entry.</p>
      </details>
    </section>

    <!-- LEAD MAGNET: email capture -->
    <section class="lead-magnet" aria-labelledby="leadTitle">
      <div class="wrap">
        <h2 id="leadTitle">Receive the next circle</h2>
        <p>Sign up for quiet notices: early access to tickets, occasional reflections from {{FACILITATOR_NAME}}, and a downloadable pre-ritual checklist.</p>
        <form id="leadForm" class="lead-form">
          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@email.com" required>
          <button type="submit" class="btn">Join the list</button>
        </form>
        <p class="privacy">We respect your inbox. Unsubscribe anytime.</p>
      </div>
    </section>

    <!-- CTA block: inviting + simple -->
    <section class="final-cta wrap">
      <h2>Reserve a place in the sound</h2>
      <p>Spaces are intimate. We recommend booking early to ensure a restful seat.</p>
      <p class="actions"><a class="btn large" href="/book.html">Book a session</a> <a class="ghost" href="/pricing.html">See rates</a></p>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="col">
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{VENUE_NAME}} • {{CITY}}, {{STATE}}</address>
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
      </div>
      <div class="col">
        <nav>
          <a href="/about.html">About</a>
          <a href="/faq.html">FAQ</a>
          <a href="/contact.html">Contact</a>
        </nav>
      </div>
      <div class="col">
        <small>© {{BUSINESS_NAME}} • All rights reserved</small>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
