{"path":"assets/css/styles.css","content":"/* Aura editorial — sensory + premium */
:root{
  --bg:#fbfbfd;
  --muted:#70707a;
  --accent:#6b5bff;
  --soft:#efe9ff;
  --surface:#ffffff;
  --glass:rgba(255,255,255,0.7);
  --radius:14px;
  --wrap:1100px;
  --mono: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
}
*{box-sizing:border-box}
body.aura{font-family:var(--mono);color:#222;background:linear-gradient(180deg,#fcfdff 0%,var(--bg) 100%);margin:0}
.wrap{max-width:var(--wrap);margin:0 auto;padding:28px}
.site-header{backdrop-filter: blur(6px);background:linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0.4));position:sticky;top:0;z-index:20;border-bottom:1px solid rgba(100,90,160,0.06)}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.brand{font-weight:700;letter-spacing:0.4px;color:var(--accent);text-decoration:none}
.nav{display:flex;gap:18px;margin-left:8px}
.nav a{color:var(--muted);text-decoration:none;padding:10px;border-radius:8px}
.nav a:hover{background:rgba(107,91,255,0.06);color:#2b2540}
.actions{margin-left:auto;display:flex;align-items:center;gap:12px}
.cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:10px;text-decoration:none}
#menuToggle{display:none;background:none;border:0;font-size:20px}
.hero{padding:50px 0;background-repeat:no-repeat;background-size:cover}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
.hero-copy h1{font-size:36px;margin:0 0 10px;color:#1a1730}
.lede{color:var(--muted);max-width:48ch}
.meta{list-style:none;padding:0;display:flex;gap:14px;margin:16px 0}
.meta li{font-size:14px;color:var(--muted)}
.hero-cta .btn{background:#2b2540;color:#fff;padding:10px 16px;border-radius:10px;text-decoration:none}
.hero-visual .hero-blob{width:100%;height:260px;border-radius:12px;box-shadow:0 10px 30px rgba(50,40,90,0.06)}
.social-proof{padding:26px 0}
.social-proof h2{margin:0 0 12px}
.testimonials{display:flex;gap:12px}
.testimonials blockquote{background:linear-gradient(180deg, #fff, var(--soft));border-radius:12px;padding:16px;flex:1;box-shadow:0 8px 24px rgba(100,80,200,0.06)}
.testimonials cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}
.benefits{padding:24px 0}
.benefits h2{margin-bottom:12px}
.cards{display:flex;gap:16px}
.cards article{background:var(--surface);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(40,20,80,0.04)}
.process{padding:20px 0}
.flow{counter-reset:item;list-style:none;padding:0;margin:0}
.flow li{margin:12px 0;padding:12px;background:linear-gradient(180deg,#fff,rgba(240,240,250,0.8));border-radius:10px}
.flow li strong{display:block}
.what-to-bring{margin-top:10px;font-style:italic;color:var(--muted)}
.contra{font-size:13px;color:#7b2b2b;background:#fff3f3;padding:10px;border-radius:8px;margin-top:10px}
.faq{padding:18px 0}
.faq details{background:var(--surface);padding:12px;border-radius:10px;margin:10px 0}
.lead-magnet{padding:22px 0;background:linear-gradient(180deg, rgba(107,91,255,0.06), transparent)}
.lead-form{display:flex;gap:8px;align-items:center}
.lead-form input[type="email"]{padding:10px;border-radius:10px;border:1px solid #e6e6ef;flex:1}
.btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;border:0}
.ghost{background:transparent;border:1px solid rgba(40,30,100,0.06);padding:10px 12px;border-radius:10px;color:var(--muted);text-decoration:none}
.final-cta{padding:28px 0;text-align:center}
.final-cta .large{padding:14px 20px;font-size:16px}
.site-footer{border-top:1px solid rgba(80,70,160,0.04);padding:24px 0;margin-top:36px}
.site-footer .wrap{display:flex;gap:24px;align-items:center}
.site-footer .col{flex:1}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .nav{display:none}
  #menuToggle{display:block}
  .testimonials{flex-direction:column}
  .cards{flex-direction:column}
}
/* Pattern background reference */
body::before{content:'';position:fixed;inset:0;pointer-events:none;background-image:url('/assets/img/pattern.svg');opacity:0.06;mix-blend-mode:overlay}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Small interactivity: menu toggle + lead form
  const menu = document.getElementById('menuToggle');
  const nav = document.querySelector('.nav');
  if(menu && nav){
    menu.addEventListener('click', ()=>{
      const open = nav.style.display !== 'block';
      nav.style.display = open ? 'block' : '';
    });
  }

  const form = document.getElementById('leadForm');
  if(form){
    form.addEventListener('submit', (e)=>{
      e.preventDefault();
      const email = form.email.value.trim();
      if(!email) return alert('Please provide an email');
      // local optimistic UI: thank you message
      form.innerHTML = '<p class="thanks">Thank you. We will send the next gathering notice to ' + email + '.</p>';
      // Simulate network event — in real life, hook to API
      console.log('Lead captured (simulated):', email);
    });
  }

  // testimonial rotation (gentle)
  const tests = document.querySelectorAll('.testimonials blockquote');
  if(tests.length>1){
    let i=0;
    setInterval(()=>{
      tests.forEach((t,idx)=> t.style.display = (idx===i)?'block':'none');
      i = (i+1)%tests.length;
    },4500);
  }
})();"} 
